describe('Column Visibility Toggle from Settings Menu', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should toggle column visibility from settings menu', () => {
    // Verify table is visible with all columns
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="column-header-name"]').should('be.visible');
    cy.get('[data-testid="column-header-email"]').should('be.visible');
    cy.get('[data-testid="column-header-phone"]').should('be.visible');

    // Open settings menu
    cy.get('[data-testid="settings-button"]').click();
    cy.get('[data-testid="settings-menu"]').should('be.visible');

    // Verify column visibility checkboxes are visible
    cy.get('[data-testid="checkbox-name"]').should('be.visible');
    cy.get('[data-testid="checkbox-email"]').should('be.visible');
    cy.get('[data-testid="checkbox-phone"]').should('be.visible');

    // Uncheck email column
    cy.get('[data-testid="checkbox-email"]').click();
    cy.get('[data-testid="checkbox-email"]').should('not.be.checked');

    // Verify email column is hidden in table
    cy.get('[data-testid="column-header-email"]').should('not.exist');
    cy.get('[data-testid="table-row"]').should('contain', 'Name');
    cy.get('[data-testid="table-row"]').should('contain', 'Phone');

    // Close settings menu
    cy.get('[data-testid="close-settings-button"]').click();
    cy.get('[data-testid="settings-menu"]').should('not.exist');

    // Verify table is still visible
    cy.get('[data-testid="data-table"]').should('be.visible');
  });

  it('should handle toggling column visibility and persist state', () => {
    // Open settings menu
    cy.get('[data-testid="settings-button"]').click();
    cy.get('[data-testid="settings-menu"]').should('be.visible');

    // Uncheck phone column
    cy.get('[data-testid="checkbox-phone"]').click();
    cy.get('[data-testid="checkbox-phone"]').should('not.be.checked');

    // Close settings menu
    cy.get('[data-testid="close-settings-button"]').click();
    cy.get('[data-testid="settings-menu"]').should('not.exist');

    // Verify phone column is hidden
    cy.get('[data-testid="column-header-phone"]').should('not.exist');

    // Reload page to test persistence
    cy.reload();

    // Verify phone column remains hidden after reload
    cy.get('[data-testid="column-header-phone"]').should('not.exist');
    cy.get('[data-testid="column-header-name"]').should('be.visible');

    // Open settings menu again
    cy.get('[data-testid="settings-button"]').click();
    cy.get('[data-testid="settings-menu"]').should('be.visible');

    // Check if phone column checkbox is unchecked
    cy.get('[data-testid="checkbox-phone"]').should('not.be.checked');

    // Check if name and email columns are still visible
    cy.get('[data-testid="checkbox-name"]').should('be.checked');
    cy.get('[data-testid="checkbox-email"]').should('be.checked');

    // Re-enable phone column
    cy.get('[data-testid="checkbox-phone"]').click();
    cy.get('[data-testid="checkbox-phone"]').should('be.checked');

    // Close settings menu
    cy.get('[data-testid="close-settings-button"]').click();
    cy.get('[data-testid="settings-menu"]').should('not.exist');

    // Verify phone column is now visible
    cy.get('[data-testid="column-header-phone"]').should('be.visible');
  });
});
